<p class="eyebrow">Administration</p><h1>Users</h1><form method="get" action="<?= e(route('admin.users.index')) ?>" class="search-form"><label class="field"><span class="sr-only">Search users</span><input name="q" value="<?= e($query) ?>" placeholder="Search name, email or account reference"></label><button class="button" type="submit">Search</button></form><div class="table-wrap"><table><thead><tr><th>Account</th><th>Investment region</th><th>Status</th><th>Email</th><th>Registered</th><th>Last login</th></tr></thead><tbody><?php if(!$users): ?><tr><td colspan="6">No users found.</td></tr><?php else: foreach($users as $user): ?><tr><td><a href="<?= e(route('admin.users.show',['user'=>$user['id']])) ?>"><strong><?= e($user['first_name'].' '.$user['last_name']) ?></strong><br><small><?= e($user['uuid']) ?></small></a></td><td><?= e($user['country_name']??'Global') ?></td><td><span class="badge badge-<?= e(strtolower($user['account_status'])) ?>"><?= e($user['account_status']) ?></span></td><td><?= !empty($user['email_verified_at'])?'Verified':'Unverified' ?></td><td><?= e($user['created_at']) ?></td><td><?= e($user['last_login_at']??'Never') ?></td></tr><?php endforeach; endif; ?></tbody></table></div>
